const norm=v=>String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9 ]/g,' ').trim()
function editDistance(a,b){let r=Array.from({length:b.length+1},(_,i)=>i);for(let i=0;i<a.length;i++){const t=[i+1];for(let j=0;j<b.length;j++)t.push(Math.min(t[j]+1,r[j+1]+1,r[j]+(a[i]===b[j]?0:1)));r=t}return r[b.length]}
function fuzzy(q,name){q=norm(q);const t=norm(name);if(!q)return 99;if(t===q)return 0;if(t.startsWith(q))return .1;if(t.includes(q))return .2;return Math.min(...t.split(' ').map(p=>editDistance(q,p.slice(0,q.length))/Math.max(q.length,1)),editDistance(q,t)/Math.max(q.length,t.length,1))+.3}
function suggestions(q,rows,label){if(norm(q).length<2)return [];return rows.map(r=>({r,s:fuzzy(q,label(r))})).filter(x=>x.s<=.8).sort((a,b)=>a.s-b.s||String(label(a.r)).localeCompare(String(label(b.r)),'it')).slice(0,10).map(x=>x.r)}
function clubHero(p,extra=''){const theme=Object.entries(TEAM_THEMES).find(([k])=>norm(p.squadra).includes(k))?.[1]||['#176b36','#0d4828'];return '<div class="clubhero" style="--team-a:'+theme[0]+';--team-b:'+theme[1]+'"><div><small>'+esc(p.squadra||'Serie A')+'</small><h1>'+esc(p.nome)+'</h1><p>'+esc([p.ruolo_classic,p.ruolo_mantra,p.ruolo_fantastats].filter(Boolean).join(' · '))+'</p></div>'+extra+'</div>'}
const signed=v=>v==null?'—':(Number(v)>0?'+':'')+fmt(v)
const EVENT_ICONS={goals:['⚽','Gol su azione'],penaltyGoals:['⚽','Gol su rigore'],assists:['🅰️','Assist'],penaltyMissed:['❌','Rigore sbagliato'],goalsConceded:['🥅','Gol subito'],penaltySave:['🧤','Rigore parato'],penaltyWon:['🎁','Rigore procurato'],yellowCard:['🟨','Ammonizione'],redCard:['🟥','Espulsione'],ownGoals:['🙈','Autogol'],errorLeadToGoal:['🦆','Errore che porta al gol'],errorLeadToShot:['🧼','Errore che porta al tiro'],penaltyConceded:['🚨','Rigore concesso'],lineClearance:['🦸','Salvataggio sulla linea'],lastManTackle:['🛟','Contrasto ultimo uomo']}
const THRESHOLD_ICONS={bigChances:['💡','Bonus grandi occasioni'],dribbles:['💃','Bonus dribbling'],passing:['🎯','Bonus precisione passaggi'],cleanSheet:['🧱','Bonus clean sheet'],goalsConceded:['🕳️','Malus aggiuntivo: almeno 3 gol subiti'],fouls:['🪓','Malus falli'],tackles:['🫥','Malus contrasti']}
const icon=(pair,count=1,detail='')=>'<span class="event-icon" title="'+esc(pair[1]+(detail?' · '+detail:''))+'" aria-label="'+esc(pair[1]+(detail?' · '+detail:''))+'">'+(count<=6?pair[0].repeat(Math.max(1,count)):pair[0]+'×'+count)+'</span>'
function events(rs){return (rs||[]).map(r=>(EVENT_ICONS[r.key]&&Number(r.quantity)>0?icon(EVENT_ICONS[r.key],Number(r.quantity)): '')+(THRESHOLD_ICONS[r.key]&&Number(r.thresholdAdjustment)!==0&&r.thresholdAdjustment!=null?icon(THRESHOLD_ICONS[r.key],1,signed(r.thresholdAdjustment)+' FP'): '')).join('')}
function legend(){return '<details class="legend-icons"><summary>Legenda icone</summary><div>'+[...Object.values(EVENT_ICONS),...Object.values(THRESHOLD_ICONS)].map(x=>'<span>'+icon(x)+' '+esc(x[1])+'</span>').join('')+'</div><small>Verde = soglia positiva, rosso = negativa nel sistema in uso; in Flop XI il segno si inverte.</small></details>'}
