function chart(series,{rank=false}={}){const all=series.flatMap(s=>s.values.filter(x=>x[1]!=null).map(x=>x[1]));if(!all.length)return empty('Nessun dato per il grafico');const xs=[...new Set(series.flatMap(s=>s.values.map(v=>v[0])))].sort((a,b)=>a-b);let lo=rank?1:Math.min(0,...all),hi=rank?Math.max(...all,2):Math.max(1,...all);if(lo===hi)hi++;const X=x=>38+(x-xs[0])/Math.max(1,xs.at(-1)-xs[0])*570,Y=y=>16+(rank?(y-lo):(hi-y))/(hi-lo)*150;const ticks=[...new Set([...Array.from({length:5},(_,i)=>lo+(hi-lo)*i/4),...(!rank?[0]:[])])].sort((a,b)=>a-b);return '<svg class="chart" viewBox="0 0 640 200" role="img" aria-label="'+esc(rank?'Andamento posizione in classifica':'Andamento fantapunti')+'">'+ticks.map(y=>'<line class="'+(!rank&&y===0?'zero-line':'')+'" x1="38" x2="608" y1="'+Y(y)+'" y2="'+Y(y)+'"/><text x="30" text-anchor="end" y="'+(Y(y)+4)+'">'+fmt(Math.round(y*10)/10)+'</text>').join('')+xs.filter((x,i)=>xs.length<=12||i%Math.ceil(xs.length/12)===0).map(x=>'<text text-anchor="middle" x="'+X(x)+'" y="188">'+x+'</text>').join('')+series.map((s,i)=>{let seg=[],out='';const flush=()=>{if(seg.length)out+='<polyline fill="none" stroke="'+colors[i%colors.length]+'" stroke-width="2.5" stroke-linejoin="round" points="'+seg.map(([x,y])=>X(x)+','+Y(y)).join(' ')+'"/>';seg=[]};for(const v of s.values){if(v[1]==null)flush();else seg.push(v)}flush();return out+s.values.filter(v=>v[1]!=null).map(([x,y,url])=>url?'<a href="#'+url+'"><circle cx="'+X(x)+'" cy="'+Y(y)+'" r="5" fill="'+colors[i%colors.length]+'"><title>GW'+x+' · '+fmt(y)+'</title></circle></a>':'<circle cx="'+X(x)+'" cy="'+Y(y)+'" r="3" fill="'+colors[i%colors.length]+'"/>').join('')}).join('')+'</svg><div class="legend">'+series.map((s,i)=>'<span><i style="background:'+colors[i%colors.length]+'"></i>'+esc(s.name)+'</span>').join('')+'</div>'}
function ranks(c){const accum=new Map(c.standings.map(r=>[r.Utente,{pts:0,fp:0}])),res={};for(const g of c.gws){for(const r of c.standings){const v=accum.get(r.Utente);v.pts+=n(r['GW'+g]);v.fp+=n(teamScore(c.id,g,r.Utente))}res[g]=[...accum].sort((a,b)=>b[1].pts-a[1].pts||b[1].fp-a[1].fp).map(([t])=>t)}return res}
const HOME_ROLE_LABELS={P:'Portieri',D:'Difensori',C:'Centrocampisti',A:'Attaccanti'}
const HOME_MODE_LABELS={normal:'Normale',fantastats:'FantaStats',flop:'Flop XI'}
