function goalMeter(c,score){if(c.kind==='formula1')return '';const p=unlimitedGoalProgress(score,c.goalBands?.thresholds);if(!p)return '';return '<div class="notice">Prossimo gol ('+(p.goals+1)+'°): '+fmt(p.nextThreshold)+' FP · mancano '+fmt(p.missing)+' FP<div class="bar"><i style="width:'+p.progress+'%"></i></div></div>'}
